    gb.face(A(-hw, y - 0.15, -hd), A(hw, y - 0.15, -hd), A(hw, top, 0), A(-hw, top, 0), [0, 0, w / 3, 0, w / 3, hd / 3, 0, hd / 3], { ...attrs, aLayer: roofLayer });
    triangle(gb, A(w / 2, y, -d / 2), A(w / 2, y, d / 2), A(w / 2, top, 0), gableLayer, attrs, d);
    triangle(gb, A(-w / 2, y, d / 2), A(-w / 2, y, -d / 2), A(-w / 2, top, 0), gableLayer, attrs, d);
