    gb.face(A(-hw, y - 0.15, hd), A(-hw, y - 0.15, -hd), A(0, top, -hd), A(0, top, hd), [0, 0, d / 3, 0, d / 3, hw / 3, 0, hw / 3], { ...attrs, aLayer: roofLayer });
