  gb.face(A(-hw, y0, -hd), A(hw, y0, -hd), A(ridge, top, 0), A(-ridge, top, 0), uvA, { ...attrs, aLayer: roofLayer });
  triangle(gb, A(hw, y0, -hd), A(hw, y0, hd), A(ridge, top, 0), roofLayer, attrs, d);
  triangle(gb, A(-hw, y0, hd), A(-hw, y0, -hd), A(-ridge, top, 0), roofLayer, attrs, d);
