    localBox(gb, b, F_, u, y + 1.1, v + side * 0.06, 1.5, 2.2, 0.12, F2.door, attrs);
    localBox(gb, b, F_, u, y + 2.55, v + side * 0.8, 2.4, 0.14, 1.6, F2.concrete, attrs);
    localBox(gb, b, F_, u, y + 0.08, v + side * 0.9, 2.6, 0.16, 1.8, F2.concrete, attrs);
