      prismWalls(gb, b, F_, 0, 0, b.w, b.d, base, base + 4, F2.shopfront, 4.5, 4, a);
      prismWalls(gb, b, F_, 0, 0, b.w, b.d, base + 4, top, wallLayer, 3.6, fh, a, 1);
